package vista;
import dao.EstudianteDAO;import modelo.Estudiante;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;
public class EstudiantesFrame extends JFrame {private final EstudianteDAO dao=new EstudianteDAO();private final DefaultTableModel model=new DefaultTableModel(new Object[]{"ID","Nombre","RUT","Curso","Correo"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);public EstudiantesFrame(){super("Gestión de estudiantes");setSize(800,480);setLocationRelativeTo(null);setLayout(new BorderLayout());add(new JScrollPane(table),BorderLayout.CENTER);JPanel p=new JPanel();JButton refresh=new JButton("Actualizar"),add=new JButton("Registrar"),edit=new JButton("Modificar"),del=new JButton("Eliminar");p.add(refresh);p.add(add);p.add(edit);p.add(del);add(p,BorderLayout.SOUTH);refresh.addActionListener(e->load());add.addActionListener(e->form(null));edit.addActionListener(e->{int r=table.getSelectedRow();if(r<0)msg("Selecciona un estudiante.");else form(r);});del.addActionListener(e->delete());load();}
 private void msg(String s){JOptionPane.showMessageDialog(this,s);}private void load(){try{model.setRowCount(0);for(Estudiante e:dao.listar())model.addRow(new Object[]{e.getId(),e.getNombre(),e.getRut(),e.getCurso(),e.getCorreo()});}catch(Exception e){msg("Error: "+e.getMessage());}}
 private void form(Integer r){JTextField[] f=new JTextField[4];String[] labs={"Nombre","RUT","Curso","Correo"};JPanel p=new JPanel(new GridLayout(4,2,5,5));for(int i=0;i<4;i++){f[i]=new JTextField(r==null?"":String.valueOf(model.getValueAt(r,i+1)));p.add(new JLabel(labs[i]));p.add(f[i]);}if(JOptionPane.showConfirmDialog(this,p,r==null?"Registrar estudiante":"Modificar estudiante",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{Estudiante e=new Estudiante(r==null?0:(int)model.getValueAt(r,0),f[0].getText().trim(),f[1].getText().trim(),f[2].getText().trim(),f[3].getText().trim());if(r==null)dao.guardar(e);else dao.actualizar(e);load();}catch(Exception ex){msg("No se pudo guardar: "+ex.getMessage());}}
 private void delete(){int r=table.getSelectedRow();if(r<0){msg("Selecciona un estudiante.");return;}if(JOptionPane.showConfirmDialog(this,"¿Eliminar estudiante?","Confirmar",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{dao.eliminar((int)model.getValueAt(r,0));load();}catch(Exception e){msg("No se puede eliminar si tiene historial de préstamos. "+e.getMessage());}}
}